INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l51',3,11,51,'Predicting the Future','预测未来','过去将来时 would(过去看未来)+ when 引导的时间定语从句(a time when …)、could (not) have done(对过去的推测)、否定词 Nor 置句首的倒装、as … as 同级比较 + 形容词 + enough to do、固定搭配 take over / be capable of doing / relieve sb of sth / dismiss the idea that(原创承载 NCE3 第三册 L51 考点·无需净化:计算机发展史科普——工程师预见多种计算机用途,却没能预见国际互联网;把英国工程师 Bagrit 改为虚构美国工程师 Leon Barrett;美式化拼写)','众所周知,预测未来是非常困难的。举个例子:在 20 世纪 70 年代中叶,又有谁能想到,到了 20 世纪末,计算机会像电视机一样在家家户户中普及呢?在 70 年代,计算机已经相当普及了,但只用在大公司、政府部门和大机构里,它们被称作主机。这些主机确实很大,常常占据整间装有空调的房间,雇用专职的技师,而且要靠专门编写的软件才能运行。虽然这类大型机器至今仍然存在,但它们的许多功能已经被体积虽小却功能强大、我们常说的“个人电脑”(PC)所接管。1975 年,美国推出了一台被称为“牛郎星”的原始机型。严格说来,它可以算是第一台“家用电脑”,并且指明了未来的方向。70 年代末,继“牛郎星”之后,又出现了一款叫作“苹果”的机型。80 年代初,计算机行业的巨头——美国国际商用机器公司(IBM)——生产出了世界上第一台个人电脑。它运行在一种叫作“磁盘操作系统”(DOS)的操作系统上,而这套系统是由当时规模还很小、名叫微软的公司开发的。IBM 的个人电脑被大量仿制。从那些简陋的开端,我们看到了今天普遍使用的、简便好用的家用电脑和多媒体机器的发展。想想这些发展离今天有多近,就更觉得非同寻常:早在 20 世纪 60 年代,一位名叫莱昂·巴瑞特的美国工程师,就已经能预见我们今天所知道的一些计算机用途了。巴瑞特并不接受“计算机会学会自己‘思考’、会‘统治世界’”这种想法,而这种想法在当时是人们乐于相信的。巴瑞特预见到,有一天计算机会小到能握在手里,会能够提供有关交通拥堵的信息、并建议可供选择的其他路线,会在医院里帮助医生诊断疾病,会使办公人员和会计免除枯燥、重复的文书工作。所有这些用途如今都已司空见惯。当然了,莱昂·巴瑞特根本不可能预见到国际互联网的出现——这个让我们能通过相连的网络、与世界上任何地方的任何人即时通讯的全球系统。他也无法预见,我们竟能利用互联网查找任何已知话题的信息,从而在家里的屏幕上阅读,愿意的话甚至还能打印出来。计算机变得越来越小、越来越强、越来越便宜。这正是巴瑞特的预言如此了不起的地方。要是他,或者像他那样的人今天还在世,或许能告诉我们未来五十年会是什么样子。','{"q":"Listen and answer — What was the ''future'' electronic development that Leon Barrett wasn''t able to foresee?","options":["The Internet","The personal computer","The mainframe machine","The pocket calculator"],"answer_index":0}'::jsonb,'{"title":"过去将来 would / could have done / Nor 倒装 / as…as·enough to do / take over·be capable of","intro":"①过去看未来用过去将来时 would:He predicted that computers would be small。②when 引导时间定语从句:a time when computers would be small。③could (not) have done:对过去的推测“(不)可能做过”:could not have foreseen。④否定词 Nor 置句首,分句要倒装:Nor could he have foreseen …。⑤as + 形容词 + as:与…一样;形容词 + enough to do:足够…以至于能。⑥固定搭配:take over(接管)、be capable of doing(能够)、relieve sb of sth(使某人免除)、dismiss the idea that …。","table":{"headers":["用法","意思","例子"],"rows":[["would(过去将来) / a time when …","过去看未来 / …的时候","a time when computers would be small"],["could (not) have done","对过去的推测","could not have foreseen the Internet"],["Nor + 倒装","也不…(倒装)","Nor could he have foreseen …"],["as … as / enough to do","与…一样 / 足够…能","as common as TV sets"]]},"specialRules":[{"rule":"Nor/Neither 等否定词置句首时,分句要把助动词/情态动词提前倒装:Nor could he …(× Nor he could …)。","mark":"Nor could he …"},{"rule":"could not have + 过去分词表示“过去不可能做过”;have 不能省,过去分词不能写成过去式(foreseen 不是 foresaw)。","mark":"could not have foreseen"},{"rule":"美式拼写:program(英式 programme)、organization(英式 organisation)、center(英式 centre)。本课已按美语写。","mark":"program / organization"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l51',1,NULL,'Predicting the future is notoriously difficult. Who could have imagined, back in the mid-1970s, that by the end of the twentieth century computers would be as common in people''s homes as TV sets? In the 1970s, computers were common enough, but only in big business, government offices, and large organizations. These were the so-called mainframe machines.','众所周知,预测未来是非常困难的。谁能想到,在 20 世纪 70 年代中叶,到了 20 世纪末,计算机会像电视机一样在家家户户中普及呢?在 70 年代,计算机已经相当普及了,但只用在大公司、政府部门和大机构里,它们被称作主机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l51',2,NULL,'Mainframe computers were very large indeed, often filling whole air-conditioned rooms, employing full-time technicians, and running on specially written software. Though these large machines still exist, many of their functions have been taken over by the small, powerful personal computers commonly known as PCs.','这些主机确实很大,常常占据整间装有空调的房间,雇用专职的技师,而且要靠专门编写的软件才能运行。虽然这类大型机器至今仍然存在,但它们的许多功能已经被体积虽小却功能强大、我们常说的“个人电脑”(PC)所接管。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l51',3,NULL,'In 1975, a primitive machine called the Altair was launched in the United States. It can fairly be described as the first ''home computer,'' and it pointed the way to the future. This was followed, at the end of the 1970s, by a machine called the Apple. In the early 1980s, the computer giant IBM produced the world''s first Personal Computer. It ran on an ''operating system'' called DOS, made by a then small company named Microsoft. The IBM Personal Computer was widely copied. From those humble beginnings, we have seen the development of the user-friendly home computers and multimedia machines that are in common use today.','1975 年,美国推出了一台被称为“牛郎星”的原始机型。严格说来,它可以算是第一台“家用电脑”,并且指明了未来的方向。70 年代末,继“牛郎星”之后,又出现了一款叫作“苹果”的机型。80 年代初,计算机行业的巨头——美国国际商用机器公司(IBM)——生产出了世界上第一台个人电脑。它运行在一种叫作“磁盘操作系统”(DOS)的操作系统上,而这套系统是由当时规模还很小、名叫微软的公司开发的。IBM 的个人电脑被大量仿制。从那些简陋的开端,我们看到了今天普遍使用的、简便好用的家用电脑和多媒体机器的发展。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l51',4,NULL,'Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s an American engineer named Leon Barrett was able to predict some of the uses of computers we know today. Barrett dismissed the idea that computers would learn to ''think'' for themselves and would ''rule the world,'' which people liked to believe in those days.','想想这些发展离今天有多近,就更觉得非同寻常:早在 20 世纪 60 年代,一位名叫莱昂·巴瑞特的美国工程师,就已经能预见我们今天所知道的一些计算机用途了。巴瑞特并不接受“计算机会学会自己‘思考’、会‘统治世界’”这种想法,而这种想法在当时是人们乐于相信的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l51',5,NULL,'Barrett foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams and suggesting alternative routes, when they would be used in hospitals to help doctors diagnose illnesses, and when they would relieve office workers and accountants of dull, repetitive clerical work. Of course, Leon Barrett could not possibly have foreseen the development of the Internet, the worldwide system that lets us communicate instantly with anyone anywhere through linked networks. Nor could he have foreseen how we would use the Internet to find information on every known subject. Computers have become smaller and smaller, more and more powerful, and cheaper and cheaper. If he were alive today, he might be able to tell us what to expect in the next fifty years.','巴瑞特预见到,有一天计算机会小到能握在手里,会能够提供有关交通拥堵的信息、并建议可供选择的其他路线,会在医院里帮助医生诊断疾病,会使办公人员和会计免除枯燥、重复的文书工作。当然了,莱昂·巴瑞特根本不可能预见到国际互联网的出现——这个让我们能通过相连的网络、与世界上任何地方的任何人即时通讯的全球系统。他也无法预见,我们竟能利用互联网查找任何已知话题的信息。计算机变得越来越小、越来越强、越来越便宜。要是他今天还在世,或许能告诉我们未来五十年会是什么样子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
