INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l51','take over','',NULL,'/teɪk ˈoʊvər/','PCs have taken over many functions of the mainframe.','个人电脑接管了主机的许多功能。','A new manager took over the team.','一位新经理接管了这个团队。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l51','be capable of','',NULL,'/bi ˈkeɪpəbəl əv/','Computers are capable of amazing things.','计算机能做出惊人的事。','She is capable of great kindness.','她能表现出极大的善意。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l51','point the way','',NULL,'/pɔɪnt ðə weɪ/','The Altair pointed the way to the future.','“牛郎星”指明了未来的方向。','His research pointed the way forward.','他的研究指明了前进的方向。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l51','relieve sb of','',NULL,'/rɪˈliːv ˈsʌmbədi əv/','Computers relieve workers of dull tasks.','计算机使工人免除枯燥的活儿。','The new tool relieved us of hours of work.','这个新工具替我们省下了好几个小时的活儿。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp1','choice','{"stem":"\"Barrett foresaw a time ___ computers would be small enough to hold.\"(引导时间的定语从句,填关系副词)","options":["where","when","that","which"],"answer_index":1,"stem_cn":"巴瑞特预见到有一天计算机会小到能握在手里。","explanation_cn":"先行词 a time 指时间,关系词在从句中作时间状语,用关系副词 when。✓ a time when computers would be small. ✗ which / that(此处需关系副词)/ where(指地点)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp1','choice','{"stem":"\"He predicted that computers ___ be used in hospitals one day.\"(过去看未来,用过去将来时)","options":["will","are","would","have"],"answer_index":2,"stem_cn":"他预言计算机有一天会用于医院。","explanation_cn":"从过去的角度看未来,用过去将来时 would + 动词原形。✓ He predicted that computers would be used … ✗ will(从现在看未来)/ are / have:过去将来用 would。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp1','choice','{"stem":"\"Who could have imagined computers ___ be in every home?\"(过去看未来:过去将来时)","options":["do","would","are","will"],"answer_index":1,"stem_cn":"谁能想到计算机会进入每个家庭?","explanation_cn":"从过去(70年代)看未来,用过去将来时 would。✓ computers would be in every home. ✗ will / are / do:过去将来用 would。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp2','choice','{"stem":"\"Who ___ have imagined this back in the 1970s?\"(对过去的推测:谁能想到,填情态动词)","options":["need","must","can","could"],"answer_index":3,"stem_cn":"谁能在70年代想到这些?","explanation_cn":"“谁能想到”是对过去可能性的推测,用 could have done;此处填情态动词 could。✓ Who could have imagined this? ✗ can(现在)/ must(必然)/ need:表“(过去)能否”用 could。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp2','choice','{"stem":"\"Barrett could not possibly ___ foreseen the Internet.\"(could not ___ foreseen:不可能预见到,填助动词)","options":["having","have","had","has"],"answer_index":1,"stem_cn":"巴瑞特根本不可能预见到国际互联网。","explanation_cn":"could not have + 过去分词,“过去不可能做过”;情态动词 could 后接 have + 过去分词。✓ could not have foreseen. ✗ has / had / having:情态动词后用 have。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp2','choice','{"stem":"\"He could not have ___ how the Internet would change life.\"(could have + 过去分词:预见到)","options":["foreseen","foreseeing","foresaw","foresee"],"answer_index":0,"stem_cn":"他无法预见互联网会如何改变生活。","explanation_cn":"could have + 过去分词;foresee 的过去分词是 foreseen。✓ could not have foreseen. ✗ foresee(原形)/ foresaw(过去式)/ foreseeing:此处用过去分词 foreseen。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp3','choice','{"stem":"\"___ could he have foreseen the rise of the Internet.\"(“也不…”,否定词置句首引起倒装,填这个词)","options":["But","Nor","So","And"],"answer_index":1,"stem_cn":"他也无法预见互联网的兴起。","explanation_cn":"“他也无法…”用否定词 Nor 置句首引起倒装。✓ Nor could he have foreseen … ✗ So(用于肯定“也…”)/ And / But:表“也不”置句首用 Nor。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp3','choice','{"stem":"\"Nor ___ he imagine computers in every pocket.\"(Nor 置句首,倒装填助动词)","options":["did he","he","could","he could"],"answer_index":2,"stem_cn":"他也想象不到计算机会装进每个人的口袋。","explanation_cn":"Nor 置句首,分句要倒装,把情态动词 could 提到主语前。✓ Nor could he imagine … ✗ he could(未倒装)/ did he(与原句情态不符)/ he:倒装后用 could。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp3','choice','{"stem":"\"He never saw the Internet, ___ did he foresee smartphones.\"(“也不”,填句首否定词引起倒装)","options":["and","nor","but","so"],"answer_index":1,"stem_cn":"他没预见到互联网,也没预见到智能手机。","explanation_cn":"“也不”接在否定句后并引起倒装,用 nor。✓ …, nor did he foresee smartphones. ✗ so / and / but:表“也不”用 nor。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp4','choice','{"stem":"\"Computers are now as common ___ TV sets.\"(“与…一样”同级比较,填第二个比较词)","options":["so","like","as","than"],"answer_index":2,"stem_cn":"如今计算机像电视机一样普及。","explanation_cn":"as + 形容词 + as,“与…一样”;第二个比较词用 as。✓ as common as TV sets. ✗ than(用于比较级)/ like / so:同级比较第二处用 as。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp4','choice','{"stem":"\"Computers became small ___ to hold in the hand.\"(形容词 + ___ + to do:足够…以至于能)","options":["so","enough","very","too"],"answer_index":1,"stem_cn":"计算机变得小到能握在手里。","explanation_cn":"形容词 + enough + to do,“足够…以至于能”;enough 放形容词之后。✓ small enough to hold. ✗ too(too…to 表否定结果)/ very / so:此处用 enough。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp4','choice','{"stem":"\"PCs are not ___ large as the old mainframes.\"(否定同级比较“不如…那么大”,填结尾前的比较词)","options":["than","such","as","more"],"answer_index":2,"stem_cn":"个人电脑不像旧主机那么大。","explanation_cn":"否定同级比较 not as/so + 形容词 + as,“不如…那么大”;结尾用 as。✓ not as large as the old mainframes. ✗ more / than / such:同级比较结尾用 as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp5','choice','{"stem":"\"Small PCs have taken ___ many functions of the mainframe.\"(take ___:接管、接收,填副词)","options":["over","up","off","in"],"answer_index":0,"stem_cn":"小型个人电脑接管了主机的许多功能。","explanation_cn":"take over,“接管、接收”;固定副词 over。✓ taken over many functions. ✗ off / up / in:take 搭配 over。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp5','choice','{"stem":"\"Computers are capable ___ providing traffic information.\"(be capable ___ doing:能够,填介词)","options":["in","to","for","of"],"answer_index":3,"stem_cn":"计算机能够提供交通信息。","explanation_cn":"be capable of doing,“能够做”;固定介词 of + 动名词。✓ capable of providing information. ✗ to / for / in:capable 搭配 of。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp5','choice','{"stem":"\"Computers relieve office workers ___ repetitive work.\"(relieve sb ___ sth:免除某人…,填介词)","options":["of","from","with","to"],"answer_index":0,"stem_cn":"计算机使办公人员免除重复劳动。","explanation_cn":"relieve sb of sth,“使某人免除…”;固定介词 of。✓ relieve office workers of repetitive work. ✗ from / with / to:relieve 搭配 of。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp6','choice','{"stem":"\"To ease or lessen someone''s burden is to ___ them of it.\"(“减轻、免除”用哪个词)","options":["add","relieve","force","ignore"],"answer_index":1,"stem_cn":"减轻、免除某人的负担。","explanation_cn":"减轻、免除负担是 relieve。✓ relieve workers of dull work. ✗ add 增加;✗ force 强迫;✗ ignore 忽视——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp6','choice','{"stem":"\"Work that is dull and done over and over is ___.\"(“重复的”用哪个词)","options":["creative","rare","exciting","repetitive"],"answer_index":3,"stem_cn":"枯燥、一遍遍重复的工作。","explanation_cn":"枯燥、一遍遍重复是 repetitive。✓ dull, repetitive clerical work. ✗ creative 有创意;✗ rare 稀少;✗ exciting 令人兴奋——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',5,'am3_l51_gp6','choice','{"stem":"\"A doctor who identifies an illness is said to ___ it.\"(“诊断”用哪个词)","options":["diagnose","cause","hide","cure"],"answer_index":0,"stem_cn":"医生查明、诊断疾病。","explanation_cn":"查明、诊断疾病是 diagnose。✓ help doctors diagnose illnesses. ✗ cure 治愈;✗ cause 引起;✗ hide 隐藏——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',6,NULL,'choice','{"stem":"notoriously 的意思是:","options":["正式地","秘密地","众所周知地(尤指坏事)","偶然地"],"answer_index":2,"explanation_cn":"notoriously = 众所周知地(尤指坏事、缺点)。✓ notoriously difficult 出了名地难。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',6,NULL,'choice','{"stem":"mainframe 的意思是:","options":["主机,中央处理机","键盘","网线","屏幕"],"answer_index":0,"explanation_cn":"mainframe = 主机、中央处理机。✓ the so-called mainframe machines 所谓的主机。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',6,NULL,'choice','{"stem":"relieve 的意思是:","options":["忽视","制造","加重","减轻,免除"],"answer_index":3,"explanation_cn":"relieve = 减轻、免除。✓ relieve office workers of dull work 使办公人员免除枯燥工作。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',6,NULL,'choice','{"stem":"diagnose 的意思是:","options":["隐瞒","治愈","诊断","传染"],"answer_index":2,"explanation_cn":"diagnose = 诊断。✓ help doctors diagnose illnesses 帮助医生诊断疾病。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',6,NULL,'choice','{"stem":"repetitive 的意思是:","options":["新颖的","重复的","复杂的","短暂的"],"answer_index":1,"explanation_cn":"repetitive = 重复的。✓ repetitive clerical work 重复的文书工作。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',6,NULL,'choice','{"stem":"alternative 的意思是:","options":["危险的","唯一的","可供选择的","昂贵的"],"answer_index":2,"explanation_cn":"alternative = 可供选择的。✓ suggesting alternative routes 建议其他可选路线。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',7,NULL,'cloze','{"stem":"第 1 空","context":"Predicting the future is notoriously difficult. Who could ___1___ imagined in the 1970s that computers would one day be as common ___2___ TV sets? Small PCs have taken ___3___ many functions of the old mainframes. Leon Barrett foresaw many computer uses, but he could not possibly have foreseen the Internet — nor ___4___ he have foreseen how we would use it to find information on any subject.","blank_no":1,"options":["have","has","had","having"],"answer_index":0,"explanation_cn":"could have + 过去分词,对过去的推测;could 后接 have。✓ Who could have imagined …"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',7,NULL,'cloze','{"stem":"第 2 空","context":"Predicting the future is notoriously difficult. Who could ___1___ imagined in the 1970s that computers would one day be as common ___2___ TV sets? Small PCs have taken ___3___ many functions of the old mainframes. Leon Barrett foresaw many computer uses, but he could not possibly have foreseen the Internet — nor ___4___ he have foreseen how we would use it to find information on any subject.","blank_no":2,"options":["as","than","like","so"],"answer_index":0,"explanation_cn":"as + 形容词 + as,“与…一样”。✓ as common as TV sets."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',7,NULL,'cloze','{"stem":"第 3 空","context":"Predicting the future is notoriously difficult. Who could ___1___ imagined in the 1970s that computers would one day be as common ___2___ TV sets? Small PCs have taken ___3___ many functions of the old mainframes. Leon Barrett foresaw many computer uses, but he could not possibly have foreseen the Internet — nor ___4___ he have foreseen how we would use it to find information on any subject.","blank_no":3,"options":["over","off","up","in"],"answer_index":0,"explanation_cn":"take over,“接管”。✓ taken over many functions of the mainframes."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',7,NULL,'cloze','{"stem":"第 4 空","context":"Predicting the future is notoriously difficult. Who could ___1___ imagined in the 1970s that computers would one day be as common ___2___ TV sets? Small PCs have taken ___3___ many functions of the old mainframes. Leon Barrett foresaw many computer uses, but he could not possibly have foreseen the Internet — nor ___4___ he have foreseen how we would use it to find information on any subject.","blank_no":4,"options":["could","can","did","would"],"answer_index":0,"explanation_cn":"Nor 置句首倒装,把情态动词 could 提前。✓ nor could he have foreseen …"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',8,NULL,'choice','{"stem":"What ''future'' electronic development was Leon Barrett unable to foresee?","options":["The mainframe","The Internet","The telephone","The personal computer"],"answer_index":1,"explanation_cn":"录音说巴瑞特预见了许多用途,却根本不可能预见到国际互联网。✓ the Internet."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',8,NULL,'choice','{"stem":"What did Barrett correctly predict about computers?","options":["That they would replace televisions","That they would never be affordable","That they would rule the world","They would be small enough to hold and would help doctors and office workers"],"answer_index":3,"explanation_cn":"录音说他预见计算机会小到能握在手里,并能帮医生诊断、替办公人员省去重复劳动。✓ small enough; help doctors and workers."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',8,NULL,'choice','{"stem":"What were the large early computers called?","options":["Multimedia machines","Personal computers","Mainframe machines","Home computers"],"answer_index":2,"explanation_cn":"录音说早期又大又占整间房的计算机被称作主机。✓ mainframe machines."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',9,NULL,'choice','{"stem":"你想说\"巴瑞特根本不可能预见到互联网\"(could not have done):","options":["Barrett could not possibly have foreseen the Internet.","Barrett could not possibly have foresaw the Internet.","Barrett could not possibly foreseen the Internet.","Barrett can not possibly have foreseen the Internet."],"answer_index":0,"explanation_cn":"could not have + 过去分词;have 不能省,过去分词用 foreseen(不是 foresaw);could 不能换成 can。✓ could not possibly have foreseen … 场合:说“(过去)根本不可能预见到”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',9,NULL,'choice','{"stem":"你想说\"他也无法预见互联网的兴起\"(Nor 句首倒装):","options":["Nor he could have foreseen the rise of the Internet.","Nor have he could foreseen the rise of the Internet.","Nor did he could foresee the rise of the Internet.","Nor could he have foreseen the rise of the Internet."],"answer_index":3,"explanation_cn":"Nor 置句首,分句要倒装(Nor could he …),不能保留正常语序,也不用 did/have 乱套。✓ Nor could he have foreseen … 场合:表达“他也无法…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',9,NULL,'choice','{"stem":"你想说\"小型电脑接管了主机的许多功能\"(take over):","options":["Small computers have take over many functions of the mainframe.","Small computers have taken over many functions of the mainframe.","Small computers have taken many functions over of the mainframe.","Small computers have taken off many functions of the mainframe."],"answer_index":1,"explanation_cn":"take over 是固定搭配,over 紧跟 taken;不能拆开、不用 take(要用过去分词 taken)、不用 taken off。✓ have taken over many functions. 场合:表达“接管了…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"relieve 的意思是:","options":["加重","减轻,免除","制造","忽视"],"answer_index":1,"explanation_cn":"relieve = 减轻、免除。✓ relieve workers of dull work."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"repetitive 的意思是:","options":["短暂的","新颖的","重复的","复杂的"],"answer_index":2,"explanation_cn":"repetitive = 重复的。✓ dull, repetitive clerical work."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"\"Who ___ have imagined this back in the 1970s?\"(对过去的推测:谁能想到,填情态动词)","options":["must","can","need","could"],"answer_index":3,"stem_cn":"谁能在70年代想到这些?","explanation_cn":"对过去的推测“谁能想到”,用 could (have done)。✓ Who could have imagined this? ✗ can / must / need。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"\"___ could he have foreseen the rise of the Internet.\"(否定词置句首,后接倒装)","options":["So","And","Nor","But"],"answer_index":2,"stem_cn":"他也无法预见互联网的兴起。","explanation_cn":"“他也无法…”用否定词 Nor 置句首引起倒装。✓ Nor could he have foreseen … ✗ So / And / But。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"\"take over\" 的意思是:","options":["拿走","接管、接收","起飞","推翻"],"answer_index":1,"explanation_cn":"take over = 接管、接收。✓ taken over many functions 接管了许多功能。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"\"be capable of\" 的意思是:","options":["负责","害怕","有能力做、能够","拒绝"],"answer_index":2,"explanation_cn":"be capable of = 有能力做、能够。✓ capable of providing information 能够提供信息。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"How did Leon Barrett''s view of computers differ from what people believed in his day?","options":["He predicted computers would disappear","He dismissed the idea that computers would ''think'' and ''rule the world''","He thought computers would never be useful","He believed computers would stay huge forever"],"answer_index":1,"passage":"Predicting the future is notoriously difficult. Who could have imagined, back in the mid-1970s, that by the end of the twentieth century computers would be as common in people''s homes as TV sets? In the 1970s, computers were common enough, but only in big business, government offices, and large organizations. These were the so-called mainframe machines. Mainframe computers were very large indeed, often filling whole air-conditioned rooms, employing full-time technicians, and running on specially written software. Though these large machines still exist, many of their functions have been taken over by the small, powerful personal computers commonly known as PCs. In 1975, a primitive machine called the Altair was launched in the United States. It can fairly be described as the first ''home computer,'' and it pointed the way to the future. This was followed, at the end of the 1970s, by a machine called the Apple. In the early 1980s, the computer giant IBM produced the world''s first Personal Computer. It ran on an ''operating system'' called DOS, made by a then small company named Microsoft. The IBM Personal Computer was widely copied. From those humble beginnings, we have seen the development of the user-friendly home computers and multimedia machines that are in common use today. Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s an American engineer named Leon Barrett was able to predict some of the uses of computers we know today. Barrett dismissed the idea that computers would learn to ''think'' for themselves and would ''rule the world,'' which people liked to believe in those days. Barrett foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams and suggesting alternative routes, when they would be used in hospitals to help doctors diagnose illnesses, and when they would relieve office workers and accountants of dull, repetitive clerical work. All these uses have become commonplace. Of course, Leon Barrett could not possibly have foreseen the development of the Internet, the worldwide system that lets us communicate instantly with anyone anywhere through linked networks. Nor could he have foreseen how we would use the Internet to find information on every known subject, so that we can read it on a screen at home and even print it out if we want to. Computers have become smaller and smaller, more and more powerful, and cheaper and cheaper. This is what makes Barrett''s predictions so remarkable. If he, or someone like him, were alive today, he might be able to tell us what to expect in the next fifty years.","explanation_cn":"课文说人们当时爱信计算机会自己思考、统治世界,巴瑞特却不接受这种想法。✓ dismissed the idea that …"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"Which of these did Barrett correctly foresee?","options":["Computers that could feel emotions","Computers replacing all human jobs","The end of all mainframes","Computers helping doctors diagnose illnesses and relieving office workers of clerical work"],"answer_index":3,"passage":"Predicting the future is notoriously difficult. Who could have imagined, back in the mid-1970s, that by the end of the twentieth century computers would be as common in people''s homes as TV sets? In the 1970s, computers were common enough, but only in big business, government offices, and large organizations. These were the so-called mainframe machines. Mainframe computers were very large indeed, often filling whole air-conditioned rooms, employing full-time technicians, and running on specially written software. Though these large machines still exist, many of their functions have been taken over by the small, powerful personal computers commonly known as PCs. In 1975, a primitive machine called the Altair was launched in the United States. It can fairly be described as the first ''home computer,'' and it pointed the way to the future. This was followed, at the end of the 1970s, by a machine called the Apple. In the early 1980s, the computer giant IBM produced the world''s first Personal Computer. It ran on an ''operating system'' called DOS, made by a then small company named Microsoft. The IBM Personal Computer was widely copied. From those humble beginnings, we have seen the development of the user-friendly home computers and multimedia machines that are in common use today. Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s an American engineer named Leon Barrett was able to predict some of the uses of computers we know today. Barrett dismissed the idea that computers would learn to ''think'' for themselves and would ''rule the world,'' which people liked to believe in those days. Barrett foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams and suggesting alternative routes, when they would be used in hospitals to help doctors diagnose illnesses, and when they would relieve office workers and accountants of dull, repetitive clerical work. All these uses have become commonplace. Of course, Leon Barrett could not possibly have foreseen the development of the Internet, the worldwide system that lets us communicate instantly with anyone anywhere through linked networks. Nor could he have foreseen how we would use the Internet to find information on every known subject, so that we can read it on a screen at home and even print it out if we want to. Computers have become smaller and smaller, more and more powerful, and cheaper and cheaper. This is what makes Barrett''s predictions so remarkable. If he, or someone like him, were alive today, he might be able to tell us what to expect in the next fifty years.","explanation_cn":"课文说他预见计算机会帮医生诊断疾病、使办公人员免除重复文书工作。✓ diagnose illnesses; relieve clerical work."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"According to the passage, what pointed the way to the future in 1975?","options":["A primitive home computer called the Altair","The IBM PC","Microsoft DOS","The first Apple"],"answer_index":0,"audio":"Predicting the future is notoriously difficult. Who could have imagined, back in the mid-1970s, that by the end of the twentieth century computers would be as common in people''s homes as TV sets? In the 1970s, computers were common enough, but only in big business, government offices, and large organizations. These were the so-called mainframe machines. Mainframe computers were very large indeed, often filling whole air-conditioned rooms, employing full-time technicians, and running on specially written software. Though these large machines still exist, many of their functions have been taken over by the small, powerful personal computers commonly known as PCs. In 1975, a primitive machine called the Altair was launched in the United States. It can fairly be described as the first ''home computer,'' and it pointed the way to the future. This was followed, at the end of the 1970s, by a machine called the Apple. In the early 1980s, the computer giant IBM produced the world''s first Personal Computer. It ran on an ''operating system'' called DOS, made by a then small company named Microsoft. The IBM Personal Computer was widely copied. From those humble beginnings, we have seen the development of the user-friendly home computers and multimedia machines that are in common use today. Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s an American engineer named Leon Barrett was able to predict some of the uses of computers we know today. Barrett dismissed the idea that computers would learn to ''think'' for themselves and would ''rule the world,'' which people liked to believe in those days. Barrett foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams and suggesting alternative routes, when they would be used in hospitals to help doctors diagnose illnesses, and when they would relieve office workers and accountants of dull, repetitive clerical work. All these uses have become commonplace. Of course, Leon Barrett could not possibly have foreseen the development of the Internet, the worldwide system that lets us communicate instantly with anyone anywhere through linked networks. Nor could he have foreseen how we would use the Internet to find information on every known subject, so that we can read it on a screen at home and even print it out if we want to. Computers have become smaller and smaller, more and more powerful, and cheaper and cheaper. This is what makes Barrett''s predictions so remarkable. If he, or someone like him, were alive today, he might be able to tell us what to expect in the next fifty years.","explanation_cn":"课文说 1975 年美国推出的原始机型“牛郎星”指明了未来方向。✓ the Altair."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l51',10,NULL,'choice','{"stem":"How have computers changed over time, according to the writer?","options":["Larger and more expensive","Slower but prettier","Fewer and rarer","Smaller and smaller, more and more powerful, and cheaper and cheaper"],"answer_index":3,"audio":"Predicting the future is notoriously difficult. Who could have imagined, back in the mid-1970s, that by the end of the twentieth century computers would be as common in people''s homes as TV sets? In the 1970s, computers were common enough, but only in big business, government offices, and large organizations. These were the so-called mainframe machines. Mainframe computers were very large indeed, often filling whole air-conditioned rooms, employing full-time technicians, and running on specially written software. Though these large machines still exist, many of their functions have been taken over by the small, powerful personal computers commonly known as PCs. In 1975, a primitive machine called the Altair was launched in the United States. It can fairly be described as the first ''home computer,'' and it pointed the way to the future. This was followed, at the end of the 1970s, by a machine called the Apple. In the early 1980s, the computer giant IBM produced the world''s first Personal Computer. It ran on an ''operating system'' called DOS, made by a then small company named Microsoft. The IBM Personal Computer was widely copied. From those humble beginnings, we have seen the development of the user-friendly home computers and multimedia machines that are in common use today. Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s an American engineer named Leon Barrett was able to predict some of the uses of computers we know today. Barrett dismissed the idea that computers would learn to ''think'' for themselves and would ''rule the world,'' which people liked to believe in those days. Barrett foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams and suggesting alternative routes, when they would be used in hospitals to help doctors diagnose illnesses, and when they would relieve office workers and accountants of dull, repetitive clerical work. All these uses have become commonplace. Of course, Leon Barrett could not possibly have foreseen the development of the Internet, the worldwide system that lets us communicate instantly with anyone anywhere through linked networks. Nor could he have foreseen how we would use the Internet to find information on every known subject, so that we can read it on a screen at home and even print it out if we want to. Computers have become smaller and smaller, more and more powerful, and cheaper and cheaper. This is what makes Barrett''s predictions so remarkable. If he, or someone like him, were alive today, he might be able to tell us what to expect in the next fifty years.","explanation_cn":"课文说计算机变得越来越小、越来越强、越来越便宜。✓ smaller, more powerful, cheaper."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l52',3,11,52,'Mud Is Mud','实事求是','虚拟 were to do(If you were to ask …, he would …)+ would 表过去反复的习惯、On + 动名词(一…就…)、固定搭配 come into the possession of / cure sb of / put out / out of stock / keep a straight face、consider/find it + 名词/形容词 + to do、被动不定式 to be told / to be surprised + 过去分词短语作状语(原创承载 NCE3 第三册 L52 考点·无需净化:幽默故事——堂兄哈里到化妆品店索要子虚乌有的商品捉弄店员,某次索要“香水泥”竟真有货、破费买下,反被治好了这个恶作剧习惯;美式化 store/salesclerk/dollars/downtown/grayish)','我的堂兄哈里在他的书房里,一直摆着一只形状古怪的大瓶子。尽管瓶子被染成一种淡雅的绿色,细心的客人很快就会发现,里面装的是一种看上去黏稠、颜色发灰的东西。要是你问哈里瓶里装着什么,他会告诉你是“香水泥”。如果你表示怀疑或惊讶,他会立刻请你闻一闻,然后取出一些抹在你的皮肤上。这个简短的试验会消除你可能还有的一切疑虑——瓶里装的确实是香水泥。哈里是如何得到这种稀奇古怪的东西的,这里头有个有趣的故事,而他也很爱讲给别人听。此外,得到这瓶东西,还治好了他多年来渐渐养成的一个坏习惯。哈里过去总把走进高档化妆品店、一本正经地索要根本不存在的商品当成一大乐事。他会当场编出一些稀奇古怪的货名。一进店,他就会索要一种名叫“香影”的新香水,或者什么“不溶浴皂”。要是女店员告诉他从没听说过,他就会装出十分懊恼、不快的样子。他最爱听人说他那些子虚乌有的产品“暂时脱销”,于是他就煞有介事地保证改天再来光顾——当然,他从没来过。哈里在这些表演中是怎么绷住不笑的,我实在想象不出。要哈里讲他是怎么买下那瓶珍贵香水泥的,根本不用别人催。一天,他走进市中心一家高档商店,索要一种叫“密诺莱特”的东西。女店员一脸茫然,哈里便把这个词又慢慢地、一字一顿地说了一遍。见那女子困惑地摇头,哈里进一步解释说,“密诺莱特”是一种质地坚硬、状似琥珀的东西,可以用来去除雀斑。这番解释显然让那女子听懂了点什么,她一个货架接一个货架地找,拿出各种稀奇古怪的调制品,可没有一样符合哈里的要求。哈里装出略带不快的样子时,店员答应替他订货。被自己的“成功”冲昏了头,哈里又索要起香水泥来。他本以为店员会一脸茫然地望着他,不料这回轮到他自己吃惊了——那女子两眼立刻一亮,取出好几个瓶子摆到柜台上让哈里查看。这一回,哈里不得不认输。他拿起看上去最小的一瓶,谨慎地问了价钱。仅花二十美元就脱了身,他很高兴,便夹着那只珍贵的瓶子匆匆撤退。从那以后,哈里认定他发明的这个小把戏可能代价不菲。那只如今装点着他书房书柜的古怪瓶子,成了他头一回、也是最后一回购买稀有化妆品。','{"q":"Listen and answer — Why did Harry decide to give up his little game?","options":["The joke product he asked for turned out to be real and cost him money","He was caught by a clerk","He ran out of fake names","His cousin made him stop"],"answer_index":0}'::jsonb,'{"title":"were to do / On + 动名词 / cure sb of·keep a straight face / consider it…to do / 被动不定式","intro":"①虚拟对将来的假设:If + 主语 + were to do …, 主语 + would do …:If you were to ask …, he would tell you。②would 也可表过去反复的习惯:He would invent names。③On + 动名词,“一…就…”:On entering a store, he would ask …。④固定搭配:come into the possession of(占有)、cure sb of sth(治好)、put out(不快)、out of stock(脱销)、keep a straight face(板着脸)。⑤consider/find/think it + 名词/形容词 + to do(it 是形式词,真正内容是后面的不定式)。⑥被动不定式 to be told / to be surprised;过去分词短语作状语 Intoxicated by …。","table":{"headers":["用法","意思","例子"],"rows":[["If … were to do, … would do","对将来的虚拟假设","If you were to ask, he would tell you"],["On + 动名词","一…就…","On entering a store, he would ask …"],["cure sb of / out of stock","治好 / 脱销","cured him of a bad habit"],["consider it + 名词 + to do","认为…是…","considered it a joke to fool clerks"]]},"specialRules":[{"rule":"were to do 用于对将来不太可能情况的假设,主句用 would/could/might + 动词原形;be 动词一律用 were。","mark":"If you were to ask …"},{"rule":"On + 动名词 = as soon as …,“一…就…”;不用 In/At,动词用 -ing 形式(On entering …)。","mark":"On entering …"},{"rule":"美式:store(英式 shop)、salesclerk(英式 shop assistant)、dollars(英式 pounds)、grayish(英式 greyish)。本课已按美语写。","mark":"store / salesclerk"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l52',1,NULL,'My cousin Harry keeps a large, curiously shaped bottle on permanent display in his study. Despite the fact that the bottle is tinted a delicate shade of green, an observant visitor would soon notice that it is filled with what looks like a thick, grayish substance. If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud.','我的堂兄哈里在他的书房里,一直摆着一只形状古怪的大瓶子。尽管瓶子被染成一种淡雅的绿色,细心的客人很快就会发现,里面装的是一种看上去黏稠、颜色发灰的东西。要是你问哈里瓶里装着什么,他会告诉你是“香水泥”。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l52',2,NULL,'If you expressed doubt or surprise, he would immediately invite you to smell it and then to rub some into your skin. This brief experiment would dispel any further doubts you might have. The bottle really does contain perfumed mud. How Harry came into the possession of this outlandish stuff makes an interesting story, which he is fond of telling. What''s more, the acquisition of this bottle cured him of a bad habit he had been developing for years.','如果你表示怀疑或惊讶,他会立刻请你闻一闻,然后取出一些抹在你的皮肤上。这个简短的试验会消除你可能还有的一切疑虑——瓶里装的确实是香水泥。哈里是如何得到这种稀奇古怪的东西的,这里头有个有趣的故事,而他也很爱讲给别人听。此外,得到这瓶东西,还治好了他多年来渐渐养成的一个坏习惯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l52',3,NULL,'Harry used to consider it a great joke to walk into expensive cosmetic stores and make outrageous requests for goods that do not exist. He would invent fanciful names on the spot. On entering a store, he would ask for a new perfume called ''Scented Shadow'' or for ''insoluble bath cubes.'' If a salesclerk told him she had never heard of it, he would pretend to be considerably put out. He loved to be told that one of his imaginary products was temporarily out of stock, and he would faithfully promise to come back at some future date — but of course he never did.','哈里过去总把走进高档化妆品店、一本正经地索要根本不存在的商品当成一大乐事。他会当场编出一些稀奇古怪的货名。一进店,他就会索要一种名叫“香影”的新香水,或者什么“不溶浴皂”。要是女店员告诉他从没听说过,他就会装出十分懊恼、不快的样子。他最爱听人说他那些子虚乌有的产品“暂时脱销”,于是他就煞有介事地保证改天再来光顾——当然,他从没来过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l52',4,NULL,'How Harry managed to keep a straight face during these performances is quite beyond me. Harry does not need to be prompted to explain how he bought his precious bottle of mud. One day, he walked into an exclusive store downtown and asked for ''Myrolite.'' The salesclerk looked puzzled, and Harry repeated the word, slowly stressing each syllable. When the woman shook her head in bewilderment, Harry went on to explain that ''myrolite'' was a hard, amber-like substance that could be used to remove freckles.','哈里在这些表演中是怎么绷住不笑的,我实在想象不出。要哈里讲他是怎么买下那瓶珍贵香水泥的,根本不用别人催。一天,他走进市中心一家高档商店,索要一种叫“密诺莱特”的东西。女店员一脸茫然,哈里便把这个词又慢慢地、一字一顿地说了一遍。见那女子困惑地摇头,哈里进一步解释说,“密诺莱特”是一种质地坚硬、状似琥珀的东西,可以用来去除雀斑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l52',5,NULL,'This explanation evidently meant something to the woman, who searched shelf after shelf. She produced all sorts of weird concoctions, but none of them met Harry''s requirements. Intoxicated by his success, Harry then asked for perfumed mud. He expected the clerk to look at him in blank astonishment. However, it was his turn to be surprised, for the woman''s eyes immediately lit up and she fetched several bottles for Harry to inspect. For once, Harry had to admit defeat. He was glad to get away with a mere twenty dollars, clutching the precious bottle under his arm. From then on, Harry decided that this little game he had invented might prove to be expensive. The curious bottle, which now adorns the bookcase in his study, was his first and last purchase of rare cosmetics.','这番解释显然让那女子听懂了点什么,她一个货架接一个货架地找,拿出各种稀奇古怪的调制品,可没有一样符合哈里的要求。被自己的“成功”冲昏了头,哈里又索要起香水泥来。他本以为店员会一脸茫然地望着他,不料这回轮到他自己吃惊了——那女子两眼立刻一亮,取出好几个瓶子让哈里查看。这一回,哈里不得不认输。仅花二十美元就脱了身,他很高兴,便夹着那只珍贵的瓶子匆匆撤退。从那以后,哈里认定他发明的这个小把戏可能代价不菲。那只如今装点着他书房书柜的古怪瓶子,成了他头一回、也是最后一回购买稀有化妆品。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
