INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l53','recognize','recognise','认识、承认;拼写差异,美语 -z-') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l53','practice','practise','做法、实践;美语动词名词都 practice,英式动词 practise') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
