INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l53','act on one''s behalf','',NULL,'/ækt ɑːn wʌnz bɪˈhæf/','The Ombudsman will act on the citizen''s behalf.','司法特派员会替公民出面。','The lawyer acted on my behalf.','律师代表我出面办事。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l53','put an end to','',NULL,'/pʊt ən end tə/','His action put an end to the unfair practice.','他的行动制止了这种不公做法。','We must put an end to this waste.','我们必须制止这种浪费。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l53','be subject to','',NULL,'/bi ˈsʌbdʒɪkt tə/','The Ombudsman is not subject to political pressure.','司法特派员不受政治压力控制。','Prices are subject to change.','价格可能会有变动。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l53','look into','',NULL,'/lʊk ˈɪntə/','He sent a lawyer to look into the matter.','他派律师去调查此事。','The police will look into the complaint.','警方会调查这起投诉。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp1','choice','{"stem":"\"The Ombudsman suggested that the law ___ altered.\"(suggest that 后从句用(should)+动词原形;此处被动,填动词原形)","options":["was","to be","is","be"],"answer_index":3,"stem_cn":"司法特派员建议修改这条法律。","explanation_cn":"suggest that 后的从句用 (should) + 动词原形,should 常省略;此处被动“法律被修改”,用 (should) be altered。✓ suggest that the law be altered. ✗ is / was(要用虚拟原形)/ to be:虚拟从句用原形 be。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp1','choice','{"stem":"\"The committee demanded that every letter ___ examined in detail.\"(demand that 后从句用(should)+原形;被动填原形)","options":["been","be","was","is"],"answer_index":1,"stem_cn":"委员会要求每封信都详细审阅。","explanation_cn":"demand that 后从句同样用 (should) + 原形;被动“每封信被审阅”,用 be examined。✓ demand that every letter be examined. ✗ is / was / been:虚拟从句用原形 be。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp1','choice','{"stem":"\"He insisted that the official ___ apologize to the citizen.\"(insist that 后从句要用哪个助动词 + 动词原形)","options":["must","will","would","should"],"answer_index":3,"stem_cn":"他坚持要求那名官员向公民道歉。","explanation_cn":"insist that 后从句用 (should) + 动词原形;此处保留 should + apologize。✓ insist that the official should apologize. ✗ must / would / will:虚拟从句用 should + 原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp2','choice','{"stem":"\"The person appointed is suitably qualified ___ investigate grievances.\"(be qualified ___ do:胜任做,填不定式符号)","options":["in","to","of","for"],"answer_index":1,"stem_cn":"被任命的人完全胜任调查冤情。","explanation_cn":"be qualified to do,“胜任做某事”;后接不定式符号 to。✓ qualified to investigate grievances. ✗ for / in / of:qualified 后接不定式 to do。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp2','choice','{"stem":"\"The Ombudsman is not subject ___ political pressure.\"(be subject ___:受…控制,填介词)","options":["for","of","to","with"],"answer_index":2,"stem_cn":"司法特派员不受政治压力控制。","explanation_cn":"be subject to,“受…控制、应服从”;固定介词 to。✓ not subject to political pressure. ✗ for / of / with:subject 搭配 to。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp2','choice','{"stem":"\"If a complaint is ___, the Ombudsman will act on the citizen''s behalf.\"(be ___:有正当理由的,填过去分词)","options":["justified","justifying","justifies","justify"],"answer_index":0,"stem_cn":"如果投诉有理,特派员就会替公民出面。","explanation_cn":"be justified,“有正当理由的、站得住脚的”;用过去分词 justified。✓ if a complaint is justified. ✗ justify / justifying / justifies:此处需过去分词 justified。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp3','choice','{"stem":"\"Complaints must be made in ___.\"(in ___:以书面形式,填名词)","options":["write","writing","wrote","written"],"answer_index":1,"stem_cn":"投诉必须以书面形式提出。","explanation_cn":"in writing,“以书面形式”;固定用名词 writing。✓ complaints must be made in writing. ✗ write / written / wrote:固定搭配是 in writing。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp3','choice','{"stem":"\"The Ombudsman acts ___ the citizen''s behalf.\"(___ one''s behalf:代表某人,填介词)","options":["in","at","on","for"],"answer_index":2,"stem_cn":"司法特派员代表公民行事。","explanation_cn":"on one''s behalf,“代表某人”;固定介词 on。✓ act on the citizen''s behalf. ✗ in / at / for:固定搭配是 on one''s behalf。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp3','choice','{"stem":"\"His prompt action put an ___ to the unfair practice.\"(put an ___ to:制止、结束,填名词)","options":["off","end","out","stop"],"answer_index":1,"stem_cn":"他的果断行动制止了这种不公做法。","explanation_cn":"put an end to,“制止、结束”;固定用名词 end。✓ put an end to the unfair practice. ✗ stop / off / out:固定搭配是 put an end to。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp4','choice','{"stem":"\"He investigates complaints large and ___ from all levels of society.\"(意义相反的形容词并用,后置修饰 complaints)","options":["small","smallest","smaller","smally"],"answer_index":0,"stem_cn":"他调查社会各阶层大大小小的投诉。","explanation_cn":"意义相反的形容词并用(large and small)修饰名词时后置;此处填 small。✓ complaints large and small. ✗ smaller / smallest / smally:并列后置用原级 small。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp4','choice','{"stem":"\"The officer ___ question was firmly reprimanded.\"(“当事的、所涉及的”,___ question,置于名词后,填介词)","options":["at","of","in","on"],"answer_index":2,"stem_cn":"当事的那名警官受到严厉批评。","explanation_cn":"in question,“当事的、所涉及的”,放名词之后修饰它。✓ the officer in question. ✗ on / at / of:固定说法是 in question。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp4','choice','{"stem":"\"It was a grievance ___ against the State.\"(过去分词后置修饰 grievance:针对…的)","options":["direct","directing","to direct","directed"],"answer_index":3,"stem_cn":"那是一桩针对政府的冤情。","explanation_cn":"过去分词短语后置修饰 grievance,表被动“针对…的”。✓ a grievance directed against the State. ✗ directing(主动)/ direct / to direct:表被动用过去分词 directed。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp5','choice','{"stem":"\"The system worked ___ well that other countries adopted it.\"(“如此…以至于”,程度副词与 that 搭配)","options":["so","too","such","very"],"answer_index":0,"stem_cn":"这套制度效果很好,别国也采用了。","explanation_cn":"so + 副词 + that,“如此…以至于”;well 是副词,前用 so。✓ worked so well that other countries adopted it. ✗ such(接名词)/ very / too:接副词接 that 用 so。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp5','choice','{"stem":"\"It was impossible ___ the Ombudsman to take action.\"(it + 形容词 + ___ sb + to do:形式主语,填介词)","options":["with","for","to","of"],"answer_index":1,"stem_cn":"司法特派员起初无法采取行动。","explanation_cn":"it is + 形容词 + for sb + to do,形式主语句型;动作的执行者用 for 引出。✓ It was impossible for the Ombudsman to take action. ✗ of / to / with:此结构用 for。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp5','choice','{"stem":"\"It was only possible for him to find out ___ sending a representative.\"(“通过做…”,___ + 动名词,填介词)","options":["with","on","in","by"],"answer_index":3,"stem_cn":"他只有派代表去核实才能查明。","explanation_cn":"by + 动名词,“通过做…”。✓ find out by sending a representative. ✗ with / in / on:表方式“通过”用 by。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp6','choice','{"stem":"\"An official who is domineering and pushy is ___.\"(“高压的、专横的”用哪个词)","options":["gentle","high-handed","shy","humble"],"answer_index":1,"stem_cn":"专横、盛气凌人的官员。","explanation_cn":"专横、盛气凌人是 high-handed。✓ high-handed public officials. ✗ gentle 温和;✗ humble 谦逊;✗ shy 胆小——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp6','choice','{"stem":"\"To find out the truth for certain is to ___ it.\"(“查明、弄清”用哪个词)","options":["hide","guess","forget","ascertain"],"answer_index":3,"stem_cn":"确切地查明、弄清真相。","explanation_cn":"确切地查明、弄清是 ascertain。✓ the lawyer ascertained the truth. ✗ guess 猜测;✗ hide 隐瞒;✗ forget 忘记——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',5,'am3_l53_gp6','choice','{"stem":"\"Someone who judges unfairly before knowing the facts is ___.\"(“有偏见的、不公平的”用哪个词)","options":["patient","prejudiced","fair","kind"],"answer_index":1,"stem_cn":"未了解事实就不公判断、有偏见的。","explanation_cn":"未了解事实就不公判断、有偏见是 prejudiced。✓ prejudiced against foreigners. ✗ fair 公平;✗ kind 友善;✗ patient 耐心——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',6,NULL,'choice','{"stem":"evolve 的意思是:","options":["逐渐形成,进化","隐藏","破坏","消失"],"answer_index":0,"explanation_cn":"evolve = 逐渐形成、进化。✓ Sweden has evolved an excellent system 瑞典逐渐形成了一套好制度。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',6,NULL,'choice','{"stem":"high-handed 的意思是:","options":["谦逊的","胆小的","高压的,专横的","温和的"],"answer_index":2,"explanation_cn":"high-handed = 高压的、专横的。✓ high-handed public officials 专横的政府官员。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',6,NULL,'choice','{"stem":"incompetent 的意思是:","options":["不称职的,不够格的","勤奋的","能干的","诚实的"],"answer_index":0,"explanation_cn":"incompetent = 不称职的、不够格的。✓ incompetent officials 不称职的官员。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',6,NULL,'choice','{"stem":"safeguard 的意思是:","options":["出售","忽视","保护","攻击"],"answer_index":2,"explanation_cn":"safeguard = 保护。✓ safeguard the interest of the individual 保护个人利益。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',6,NULL,'choice','{"stem":"accusation 的意思是:","options":["表扬","谴责,指控","邀请","道歉"],"answer_index":1,"explanation_cn":"accusation = 谴责、指控。✓ denied the accusation 否认这一指控。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',6,NULL,'choice','{"stem":"ascertain 的意思是:","options":["忘记","猜测","隐瞒","查出,查明"],"answer_index":3,"explanation_cn":"ascertain = 查出、查明。✓ the lawyer ascertained the truth 律师查明了真相。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',7,NULL,'cloze','{"stem":"第 1 空","context":"Sweden has evolved an excellent system for protecting citizens from high-handed officials. The system has worked ___1___ well that other countries have adopted it. A qualified person, the Ombudsman, investigates complaints and is not subject ___2___ political pressure. If a complaint is justified, he acts ___3___ the citizen''s behalf. In one case, he even suggested to parliament that a law ___4___ altered.","blank_no":1,"options":["so","such","very","too"],"answer_index":0,"explanation_cn":"so + 副词 + that,“如此…以至于”。✓ worked so well that other countries adopted it."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',7,NULL,'cloze','{"stem":"第 2 空","context":"Sweden has evolved an excellent system for protecting citizens from high-handed officials. The system has worked ___1___ well that other countries have adopted it. A qualified person, the Ombudsman, investigates complaints and is not subject ___2___ political pressure. If a complaint is justified, he acts ___3___ the citizen''s behalf. In one case, he even suggested to parliament that a law ___4___ altered.","blank_no":2,"options":["to","for","of","with"],"answer_index":0,"explanation_cn":"be subject to,“受…控制”。✓ not subject to political pressure."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',7,NULL,'cloze','{"stem":"第 3 空","context":"Sweden has evolved an excellent system for protecting citizens from high-handed officials. The system has worked ___1___ well that other countries have adopted it. A qualified person, the Ombudsman, investigates complaints and is not subject ___2___ political pressure. If a complaint is justified, he acts ___3___ the citizen''s behalf. In one case, he even suggested to parliament that a law ___4___ altered.","blank_no":3,"options":["on","in","at","for"],"answer_index":0,"explanation_cn":"on one''s behalf,“代表某人”。✓ acts on the citizen''s behalf."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',7,NULL,'cloze','{"stem":"第 4 空","context":"Sweden has evolved an excellent system for protecting citizens from high-handed officials. The system has worked ___1___ well that other countries have adopted it. A qualified person, the Ombudsman, investigates complaints and is not subject ___2___ political pressure. If a complaint is justified, he acts ___3___ the citizen''s behalf. In one case, he even suggested to parliament that a law ___4___ altered.","blank_no":4,"options":["be","is","was","been"],"answer_index":0,"explanation_cn":"suggest that 后从句用 (should) + 原形;被动填 be altered。✓ suggested that a law be altered."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',8,NULL,'choice','{"stem":"What could not be reported in the official files?","options":["The Ombudsman''s letter","The fact that the officer was prejudiced against foreigners","The date of the complaint","The foreigner''s name"],"answer_index":1,"explanation_cn":"录音说那名警官对外国人抱有偏见这一事实,在官方档案中根本无法记载。✓ the officer''s prejudice."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',8,NULL,'choice','{"stem":"What is the job of the Swedish Ombudsman?","options":["To investigate citizens'' complaints against public officials","To write new laws","To lead the police","To collect taxes"],"answer_index":0,"explanation_cn":"录音说司法特派员的职责是调查公民对政府官员的投诉。✓ investigate complaints against officials."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',8,NULL,'choice','{"stem":"How must complaints be made to the Ombudsman?","options":["In person only","By phone","In writing","Through a lawyer"],"answer_index":2,"explanation_cn":"录音说所有投诉都必须以书面形式提出。✓ in writing."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',9,NULL,'choice','{"stem":"你想说\"他建议议会修改这条法律\"(suggest that + (should) + 动词原形):","options":["He suggested to parliament that the law is altered.","He suggested to parliament that the law was altered.","He suggested to parliament that the law be altered.","He suggested to parliament that the law altering."],"answer_index":2,"explanation_cn":"suggest that 后从句用 (should) + 动词原形,被动为 be altered;不用 is/was/altering。✓ suggested … that the law be altered. 场合:提出建议。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',9,NULL,'choice','{"stem":"你想说\"被任命的人完全胜任调查冤情\"(be qualified to do):","options":["The person appointed is qualified investigating grievances.","The person appointed is qualified to investigate grievances.","The person appointed is qualified to investigating grievances.","The person appointed is qualified for investigate grievances."],"answer_index":1,"explanation_cn":"be qualified to do,后接不定式 to investigate;不用 for、不用 -ing、不用 to + -ing。✓ qualified to investigate. 场合:说“胜任做…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',9,NULL,'choice','{"stem":"你想说\"如果投诉有理,他就会替公民出面\"(act on one''s behalf):","options":["If the complaint is justified, he will act on behalf the citizen.","If the complaint is justified, he will act the citizen''s behalf on.","If the complaint is justified, he will act in the citizen''s behalf.","If the complaint is justified, he will act on the citizen''s behalf."],"answer_index":3,"explanation_cn":"act on one''s behalf,固定搭配 on … behalf,语序不能拆开、on 不能换 in。✓ act on the citizen''s behalf. 场合:说“代表某人出面”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"high-handed 的意思是:","options":["谦逊的","温和的","胆小的","高压的,专横的"],"answer_index":3,"explanation_cn":"high-handed = 高压的、专横的。✓ high-handed public officials."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"ascertain 的意思是:","options":["隐瞒","查出,查明","猜测","忘记"],"answer_index":1,"explanation_cn":"ascertain = 查出、查明。✓ the lawyer ascertained the truth."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"\"The Ombudsman suggested that the law ___ altered.\"(suggest that 后从句用(should)+动词原形,被动填原形)","options":["was","to be","is","be"],"answer_index":3,"stem_cn":"司法特派员建议修改这条法律。","explanation_cn":"suggest that 后从句用 (should) + 动词原形,被动填 be。✓ suggested that the law be altered. ✗ is / was / to be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"\"The Ombudsman is not subject ___ political pressure.\"(be subject ___:受…控制,填介词)","options":["of","to","with","for"],"answer_index":1,"stem_cn":"司法特派员不受政治压力控制。","explanation_cn":"be subject to,“受…控制”。✓ not subject to political pressure. ✗ for / of / with。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"\"put an end to\" 的意思是:","options":["制止、结束","忽视","推迟","开始"],"answer_index":0,"explanation_cn":"put an end to = 制止、结束。✓ put an end to the unfair practice."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"\"act on one''s behalf\" 的意思是:","options":["模仿某人","反对某人","惩罚某人","代表某人行事"],"answer_index":3,"explanation_cn":"act on one''s behalf = 代表某人行事。✓ act on the citizen''s behalf."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"Why was the Ombudsman system created in Sweden?","options":["To collect more taxes","To protect individual citizens from high-handed or incompetent officials","To increase police power","To reduce the number of laws"],"answer_index":1,"passage":"The Scandinavian countries are much admired all over the world for their enlightened social policies. Sweden has evolved an excellent system for protecting the individual citizen from high-handed or incompetent public officials. The system has worked so well that it has been adopted in other countries too. The Swedes were among the first to recognize that public officials such as civil servants, police officers, health inspectors, and tax collectors can make mistakes or act over-zealously in the belief that they are serving the public. As long ago as 1809, the Swedish Parliament introduced a plan to safeguard the interest of the individual. A parliamentary committee representing all political parties appoints a person who is suitably qualified to investigate private grievances against the State. The official title of this person is ''Justitieombudsman,'' but the Swedes commonly refer to him as the ''J.O.'' or ''Ombudsman.'' The Ombudsman is not subject to political pressure. He investigates complaints large and small that come to him from all levels of society. Since complaints must be made in writing, the Ombudsman receives an average of twelve hundred letters a year, and he has eight legal assistants to help him examine every single one in detail. There is nothing secretive about the Ombudsman''s work, for his correspondence is open to public inspection. If a citizen''s complaint is justified, the Ombudsman will act on his behalf. The action he takes varies according to the nature of the complaint. He may gently reprimand an official, or he may even suggest to parliament that a law be altered. The following case is a typical example of the Ombudsman''s work. A foreigner living in a Swedish village wrote to the Ombudsman, complaining that he had been treated unfairly by an officer simply because he was a foreigner. The Ombudsman immediately wrote to the chief of police in the district, asking him to send a record of the case. There was nothing in the record to show that the foreigner''s complaint was justified, and the chief of police firmly denied the accusation. It was impossible for the Ombudsman to take action. But when he received a similar complaint from another foreigner in the same village, he immediately sent one of his lawyers to look into the matter. The lawyer ascertained that the officer had indeed treated foreigners unfairly on several occasions. The fact that the officer was prejudiced against foreigners could not be recorded in the official files. It was only possible for the Ombudsman to find this out by sending one of his representatives to check the facts. The officer in question was firmly reprimanded and was told that if any further complaints were made against him, he would be dealt with more seriously. The Ombudsman''s prompt action at once put an end to an unfair practice that might otherwise have gone unnoticed.","explanation_cn":"课文说瑞典建立这一制度,是为了保护每个公民不受专横或不称职官员的欺压。✓ protect citizens from high-handed officials."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"How did the Ombudsman finally uncover the truth about the prejudiced officer?","options":["By reading the official files","By asking the chief of police","By interviewing the officer himself","By sending one of his representatives to check the facts"],"answer_index":3,"passage":"The Scandinavian countries are much admired all over the world for their enlightened social policies. Sweden has evolved an excellent system for protecting the individual citizen from high-handed or incompetent public officials. The system has worked so well that it has been adopted in other countries too. The Swedes were among the first to recognize that public officials such as civil servants, police officers, health inspectors, and tax collectors can make mistakes or act over-zealously in the belief that they are serving the public. As long ago as 1809, the Swedish Parliament introduced a plan to safeguard the interest of the individual. A parliamentary committee representing all political parties appoints a person who is suitably qualified to investigate private grievances against the State. The official title of this person is ''Justitieombudsman,'' but the Swedes commonly refer to him as the ''J.O.'' or ''Ombudsman.'' The Ombudsman is not subject to political pressure. He investigates complaints large and small that come to him from all levels of society. Since complaints must be made in writing, the Ombudsman receives an average of twelve hundred letters a year, and he has eight legal assistants to help him examine every single one in detail. There is nothing secretive about the Ombudsman''s work, for his correspondence is open to public inspection. If a citizen''s complaint is justified, the Ombudsman will act on his behalf. The action he takes varies according to the nature of the complaint. He may gently reprimand an official, or he may even suggest to parliament that a law be altered. The following case is a typical example of the Ombudsman''s work. A foreigner living in a Swedish village wrote to the Ombudsman, complaining that he had been treated unfairly by an officer simply because he was a foreigner. The Ombudsman immediately wrote to the chief of police in the district, asking him to send a record of the case. There was nothing in the record to show that the foreigner''s complaint was justified, and the chief of police firmly denied the accusation. It was impossible for the Ombudsman to take action. But when he received a similar complaint from another foreigner in the same village, he immediately sent one of his lawyers to look into the matter. The lawyer ascertained that the officer had indeed treated foreigners unfairly on several occasions. The fact that the officer was prejudiced against foreigners could not be recorded in the official files. It was only possible for the Ombudsman to find this out by sending one of his representatives to check the facts. The officer in question was firmly reprimanded and was told that if any further complaints were made against him, he would be dealt with more seriously. The Ombudsman''s prompt action at once put an end to an unfair practice that might otherwise have gone unnoticed.","explanation_cn":"课文说那名警官有偏见的事实档案里查不到,司法特派员只有派代表去核对事实才查明。✓ sending a representative to check."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"How many letters does the Ombudsman receive on average each year?","options":["About a dozen","About ten thousand","About twelve hundred","About fifty"],"answer_index":2,"audio":"The Scandinavian countries are much admired all over the world for their enlightened social policies. Sweden has evolved an excellent system for protecting the individual citizen from high-handed or incompetent public officials. The system has worked so well that it has been adopted in other countries too. The Swedes were among the first to recognize that public officials such as civil servants, police officers, health inspectors, and tax collectors can make mistakes or act over-zealously in the belief that they are serving the public. As long ago as 1809, the Swedish Parliament introduced a plan to safeguard the interest of the individual. A parliamentary committee representing all political parties appoints a person who is suitably qualified to investigate private grievances against the State. The official title of this person is ''Justitieombudsman,'' but the Swedes commonly refer to him as the ''J.O.'' or ''Ombudsman.'' The Ombudsman is not subject to political pressure. He investigates complaints large and small that come to him from all levels of society. Since complaints must be made in writing, the Ombudsman receives an average of twelve hundred letters a year, and he has eight legal assistants to help him examine every single one in detail. There is nothing secretive about the Ombudsman''s work, for his correspondence is open to public inspection. If a citizen''s complaint is justified, the Ombudsman will act on his behalf. The action he takes varies according to the nature of the complaint. He may gently reprimand an official, or he may even suggest to parliament that a law be altered. The following case is a typical example of the Ombudsman''s work. A foreigner living in a Swedish village wrote to the Ombudsman, complaining that he had been treated unfairly by an officer simply because he was a foreigner. The Ombudsman immediately wrote to the chief of police in the district, asking him to send a record of the case. There was nothing in the record to show that the foreigner''s complaint was justified, and the chief of police firmly denied the accusation. It was impossible for the Ombudsman to take action. But when he received a similar complaint from another foreigner in the same village, he immediately sent one of his lawyers to look into the matter. The lawyer ascertained that the officer had indeed treated foreigners unfairly on several occasions. The fact that the officer was prejudiced against foreigners could not be recorded in the official files. It was only possible for the Ombudsman to find this out by sending one of his representatives to check the facts. The officer in question was firmly reprimanded and was told that if any further complaints were made against him, he would be dealt with more seriously. The Ombudsman''s prompt action at once put an end to an unfair practice that might otherwise have gone unnoticed.","explanation_cn":"课文说司法特派员每年平均收到约一千二百封信。✓ an average of twelve hundred letters."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l53',10,NULL,'choice','{"stem":"What happened to the officer in the end?","options":["He was promoted","He was firmly reprimanded and warned","He was given an award","Nothing happened to him"],"answer_index":1,"audio":"The Scandinavian countries are much admired all over the world for their enlightened social policies. Sweden has evolved an excellent system for protecting the individual citizen from high-handed or incompetent public officials. The system has worked so well that it has been adopted in other countries too. The Swedes were among the first to recognize that public officials such as civil servants, police officers, health inspectors, and tax collectors can make mistakes or act over-zealously in the belief that they are serving the public. As long ago as 1809, the Swedish Parliament introduced a plan to safeguard the interest of the individual. A parliamentary committee representing all political parties appoints a person who is suitably qualified to investigate private grievances against the State. The official title of this person is ''Justitieombudsman,'' but the Swedes commonly refer to him as the ''J.O.'' or ''Ombudsman.'' The Ombudsman is not subject to political pressure. He investigates complaints large and small that come to him from all levels of society. Since complaints must be made in writing, the Ombudsman receives an average of twelve hundred letters a year, and he has eight legal assistants to help him examine every single one in detail. There is nothing secretive about the Ombudsman''s work, for his correspondence is open to public inspection. If a citizen''s complaint is justified, the Ombudsman will act on his behalf. The action he takes varies according to the nature of the complaint. He may gently reprimand an official, or he may even suggest to parliament that a law be altered. The following case is a typical example of the Ombudsman''s work. A foreigner living in a Swedish village wrote to the Ombudsman, complaining that he had been treated unfairly by an officer simply because he was a foreigner. The Ombudsman immediately wrote to the chief of police in the district, asking him to send a record of the case. There was nothing in the record to show that the foreigner''s complaint was justified, and the chief of police firmly denied the accusation. It was impossible for the Ombudsman to take action. But when he received a similar complaint from another foreigner in the same village, he immediately sent one of his lawyers to look into the matter. The lawyer ascertained that the officer had indeed treated foreigners unfairly on several occasions. The fact that the officer was prejudiced against foreigners could not be recorded in the official files. It was only possible for the Ombudsman to find this out by sending one of his representatives to check the facts. The officer in question was firmly reprimanded and was told that if any further complaints were made against him, he would be dealt with more seriously. The Ombudsman''s prompt action at once put an end to an unfair practice that might otherwise have gone unnoticed.","explanation_cn":"课文说当事的那名警官受到严厉批评,并被告知若再有投诉会被更严肃处理。✓ firmly reprimanded and warned."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l54',3,11,54,'Instinct or Cleverness?','是本能还是机智?','不定式作宾语(be determined/manage to do)、动名词作宾语(keep/stop/give up doing)、现在分词短语作状语(Watching …, Feeling …, using …)、过去分词短语作状语(Defeated …, Planted …)、让步 no matter how / though / even though(按 Aaron 净化包生产·措辞放缓·不读源PDF:昆虫自然散文——作者想保护桃树不被聪明的蚂蚁偷吃,无论筑多少屏障都被绕过,斗智失败反而钦佩蚂蚁;把原课“向昆虫开战”等好战措辞放缓成中性描述,幽默反思人对昆虫偏见的内核保留;美式化 yard/flashlight)','我们大多数人自幼被教得害怕昆虫,把它们当作宁可避开的害虫。我们拍打苍蝇、绕开蜘蛛、把蚂蚁从食物旁赶走。可是去年夏天,一队小小的蚂蚁却教会了我转而钦佩它们。我的桃树靠着一堵暖和、避风的墙生长,到了八月,已挂满了甘美熟透的果子。我特别为这棵树自豪,下决心要保护它不被那些排着长长的、耐心的队伍、顺树干往上爬的蚂蚁偷吃。看着它们往上爬,我决定在树的根部围一圈水做屏障,自信没有一只蚂蚁能过得来。自以为聪明,我坐下来准备享受胜利。可不到一个小时,蚂蚁们就用一片落叶当桥,渡过了水。我把落叶清走,却只见它们又去试另一片。无论我筑多少道屏障,它们总能设法越过。我甚至半夜打着手电筒出去,看见它们还在我的防线周围忙碌,在黑暗中耐心地干着。第二天一早,我本盼着它们已经放弃,却发现它们找到了一条崭新的路线:它们正顺着房子的外墙往上爬,再直接落到树叶上。我不断发现新的蚁群,也忍不住一直钦佩它们的耐心。被彻底打败、却又满心惊叹,我最终放弃了斗智,让它们分享果子。我至今仍在想:是纯粹的本能在指引它们,还是它们干脆就比我聪明?我懂得了:输给一只蚂蚁,没什么好羞愧的。一个如此渺小却从不放弃的小生灵,身上总有值得钦佩的地方。','{"q":"Listen and answer — Was the writer successful in protecting his peach tree? Why not?","options":["No — the ants cleverly found new routes past every barrier he built","Yes — the water barrier worked perfectly","Yes — he sprayed the tree","No — a storm destroyed the tree"],"answer_index":0}'::jsonb,'{"title":"不定式作宾语 / 动名词作宾语 / 现在分词作状语 / 过去分词作状语 / 让步 no matter how","intro":"①有些动词/结构后接不定式作宾语:be determined to do、manage to do、decide to do。②有些动词后接动名词作宾语:keep doing、stop doing、give up doing。③现在分词短语作状语,表主动伴随:Watching them climb, I …;using a leaf as a bridge。④过去分词短语作状语,表被动:Defeated but amazed, I …。⑤让步:no matter how(无论多么)、though / even though(虽然、尽管)。","table":{"headers":["用法","意思","例子"],"rows":[["be determined / manage to do","决心/设法做(不定式)","I was determined to protect it"],["keep / stop / give up doing","不断/停止/放弃做(动名词)","I gave up trying to stop them"],["现在分词/过去分词作状语","主动伴随 / 被动","Watching …; Defeated …"],["no matter how / though","无论多么 / 虽然","No matter how many barriers I built"]]},"specialRules":[{"rule":"同一个“做某事”,在 be determined/manage/decide 后用不定式(to do),在 keep/stop/give up 后用动名词(doing),不能混。","mark":"determined to do / give up doing"},{"rule":"分词作状语时,主动/进行用现在分词(-ing),被动/完成用过去分词(-ed);逻辑主语要与主句一致。","mark":"Watching … / Defeated …"},{"rule":"美式:yard(英式 garden 指院子)、flashlight(英式 torch)。本课已按美语写。","mark":"yard / flashlight"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l54',1,NULL,'Most of us are brought up to fear insects, seeing them as pests we would rather avoid. We swat at flies, step around spiders, and shoo ants away from our food. Yet last summer, a line of tiny ants taught me to admire them instead.','我们大多数人自幼被教得害怕昆虫,把它们当作宁可避开的害虫。我们拍打苍蝇、绕开蜘蛛、把蚂蚁从食物旁赶走。可是去年夏天,一队小小的蚂蚁却教会了我转而钦佩它们。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l54',2,NULL,'My peach tree had grown against a warm, sheltered wall, and by August it was full of ripe, delicious fruit. I was especially proud of that tree, and I was determined to protect it from the ants that came marching up the trunk in a long, patient line. Watching them climb, I decided to build a small barrier of water around the base, certain that no ant could cross it.','我的桃树靠着一堵暖和、避风的墙生长,到了八月,已挂满了甘美熟透的果子。我特别为这棵树自豪,下决心要保护它不被那些排着长长的、耐心的队伍、顺树干往上爬的蚂蚁偷吃。看着它们往上爬,我决定在树的根部围一圈水做屏障,自信没有一只蚂蚁能过得来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l54',3,NULL,'Feeling clever, I sat back to enjoy my victory. But within an hour, the ants had found a way across, using a fallen leaf as a bridge. I cleared the leaf away, only to watch them try another. No matter how many barriers I built, they always managed to get past.','自以为聪明,我坐下来准备享受胜利。可不到一个小时,蚂蚁们就用一片落叶当桥,渡过了水。我把落叶清走,却只见它们又去试另一片。无论我筑多少道屏障,它们总能设法越过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l54',4,NULL,'I even went out at midnight with a flashlight and saw them still swarming around my defenses, working patiently in the dark. Early the next morning, hoping to find that they had given up, I instead discovered a brand-new route: they were climbing the wall of the house and dropping straight onto the leaves.','我甚至半夜打着手电筒出去,看见它们还在我的防线周围忙碌,在黑暗中耐心地干着。第二天一早,我本盼着它们已经放弃,却发现它们找到了一条崭新的路线:它们正顺着房子的外墙往上爬,再直接落到树叶上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l54',5,NULL,'I kept finding new columns of ants every hour, and I could not stop admiring their patience. Defeated but amazed, I finally gave up trying to outwit them and let them share the fruit. I still wonder whether it was pure instinct that guided them, or whether they were simply cleverer than I was. Losing to an ant, I have learned, is nothing to be ashamed of. There is something to admire in a creature so small that never gives up.','我不断发现新的蚁群,也忍不住一直钦佩它们的耐心。被彻底打败、却又满心惊叹,我最终放弃了斗智,让它们分享果子。我至今仍在想:是纯粹的本能在指引它们,还是它们干脆就比我聪明?我懂得了:输给一只蚂蚁,没什么好羞愧的。一个如此渺小却从不放弃的小生灵,身上总有值得钦佩的地方。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
