INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l54','bring up','',NULL,'/brɪŋ ʌp/','We are brought up to fear insects.','我们自幼被教得害怕昆虫。','She was brought up in the countryside.','她是在乡下长大的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l54','give up','',NULL,'/ɡɪv ʌp/','I gave up trying to stop them.','我放弃了阻止它们的努力。','Don''t give up so easily.','别这么轻易就放弃。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l54','no matter how','',NULL,'/noʊ ˈmætər haʊ/','No matter how hard I tried, they won.','无论我多努力,它们都赢了。','No matter how late it is, call me.','无论多晚,都给我打电话。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l54','be proud of','',NULL,'/bi praʊd əv/','I was proud of my peach tree.','我为我的桃树感到自豪。','She is proud of her work.','她为自己的工作感到自豪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp1','choice','{"stem":"\"We are brought up ___ insects and see them as pests.\"(be brought up ___ do:被教养成…,填不定式)","options":["fear","feared","to fear","fearing"],"answer_index":2,"stem_cn":"我们自幼被教得害怕昆虫,把它们当害虫。","explanation_cn":"be brought up to do sth,“被教养成做…”;后接不定式。✓ brought up to fear insects. ✗ fearing / fear / feared:此结构后接不定式 to fear。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp1','choice','{"stem":"\"I was determined ___ my peach tree from the ants.\"(be determined ___ do:决心做)","options":["to protect","protected","protect","protecting"],"answer_index":0,"stem_cn":"我决心保护我的桃树不被蚂蚁侵害。","explanation_cn":"be determined to do sth,“决心做”;后接不定式。✓ determined to protect it. ✗ protecting / protect / protected:be determined 后接不定式 to protect。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp1','choice','{"stem":"\"The ants always managed ___ past my barriers.\"(manage ___ do:设法做成)","options":["got","get","getting","to get"],"answer_index":3,"stem_cn":"蚂蚁总能设法越过我的屏障。","explanation_cn":"manage to do sth,“设法做成”;后接不定式。✓ managed to get past. ✗ getting / get / got:manage 后接不定式 to get。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp2','choice','{"stem":"\"I kept ___ new columns of ants every hour.\"(keep ___ doing:不断做,填动名词)","options":["finding","to find","find","found"],"answer_index":0,"stem_cn":"我每小时都不断发现新的蚁群。","explanation_cn":"keep doing sth,“不断做”;后接动名词。✓ kept finding new ants. ✗ to find / find / found:keep 后接动名词 finding。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp2','choice','{"stem":"\"I could not stop ___ their patience.\"(can''t stop ___ doing:忍不住一直做)","options":["admire","admiring","admired","to admire"],"answer_index":1,"stem_cn":"我忍不住一直钦佩它们的耐心。","explanation_cn":"can''t stop doing sth,“忍不住一直做”;stop 后接动名词表“停止正在做的事/忍不住做”。✓ could not stop admiring. ✗ to admire(stop to do=停下来去做,意思不符)/ admire / admired:此处用动名词 admiring。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp2','choice','{"stem":"\"I finally gave up ___ to outwit them.\"(give up ___ doing:放弃做)","options":["tried","to try","trying","try"],"answer_index":2,"stem_cn":"我最终放弃了斗智的努力。","explanation_cn":"give up doing sth,“放弃做”;后接动名词。✓ gave up trying to outwit them. ✗ to try / try / tried:give up 后接动名词 trying。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp3','choice','{"stem":"\"___ them march up the trunk, I decided to act.\"(现在分词短语作状语:看着…)","options":["Watch","To watch","Watched","Watching"],"answer_index":3,"stem_cn":"看着它们爬上树干,我决定动手。","explanation_cn":"现在分词短语作状语,主动“看着…”;逻辑动作者是 I。✓ Watching them climb, I decided … ✗ Watched(被动)/ Watch / To watch:主动伴随用 -ing。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp3','choice','{"stem":"\"___ clever, I sat back to enjoy my victory.\"(现在分词短语作状语:自以为…)","options":["Felt","Feel","Feeling","To feel"],"answer_index":2,"stem_cn":"自以为聪明,我坐下来享受胜利。","explanation_cn":"现在分词短语作状语,主动“(自)感到…”。✓ Feeling clever, I sat back … ✗ Felt / Feel / To feel:主动伴随用 -ing。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp3','choice','{"stem":"\"The ants crossed the water, ___ a fallen leaf as a bridge.\"(现在分词表方式:用…)","options":["to use","using","use","used"],"answer_index":1,"stem_cn":"蚂蚁用一片落叶当桥渡过了水。","explanation_cn":"现在分词表方式,“用…”;与主句同时主动发生。✓ crossed the water, using a leaf as a bridge. ✗ used / use / to use:表方式的主动分词用 -ing。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp4','choice','{"stem":"\"___ but amazed, I finally let them share the fruit.\"(过去分词短语作状语:被打败)","options":["Defeated","Defeat","To defeat","Defeating"],"answer_index":0,"stem_cn":"被打败却又惊叹,我最终让它们分享果实。","explanation_cn":"过去分词短语作状语,表被动“被打败”;逻辑动作者是 I(我被打败)。✓ Defeated but amazed, I … ✗ Defeating(主动)/ Defeat / To defeat:表被动用过去分词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp4','choice','{"stem":"\"___ by their cleverness, I could only admire them.\"(过去分词短语作状语:被…折服)","options":["Impress","Impressing","To impress","Impressed"],"answer_index":3,"stem_cn":"被它们的聪明折服,我只能钦佩。","explanation_cn":"过去分词短语作状语,表被动“被…折服”。✓ Impressed by their cleverness, I … ✗ Impressing(主动)/ Impress / To impress:表被动用过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp4','choice','{"stem":"\"___ against a warm wall, the peach tree grew well.\"(过去分词短语作状语:被种在…)","options":["Planted","To plant","Planting","Plant"],"answer_index":0,"stem_cn":"种在暖墙边,桃树长得很好。","explanation_cn":"过去分词短语作状语,表被动“被种在…”;tree 是被种的。✓ Planted against a warm wall, the tree grew well. ✗ Planting(主动)/ Plant / To plant:表被动用过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp5','choice','{"stem":"\"No matter ___ many barriers I built, the ants got past.\"(no matter ___:无论多少,填疑问词)","options":["what","that","how","which"],"answer_index":2,"stem_cn":"无论我筑多少屏障,蚂蚁都能过去。","explanation_cn":"no matter how + 形容词/副词,“无论多么…”;此处 how many。✓ No matter how many barriers I built … ✗ what / which / that:与 many 搭配表“无论多少”用 how。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp5','choice','{"stem":"\"___ I tried very hard, I could not stop them.\"(“虽然、尽管”,引导让步)","options":["Because","Though","Unless","So"],"answer_index":1,"stem_cn":"尽管我很努力,还是拦不住它们。","explanation_cn":"though,“虽然、尽管”,引导让步。✓ Though I tried very hard, … ✗ Because(因为)/ Unless(除非)/ So(所以)。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp5','choice','{"stem":"\"Even ___ the tape was sticky, the ants found a way.\"(even ___:即使,让步)","options":["if only","so","as","though"],"answer_index":3,"stem_cn":"即使胶带很粘,蚂蚁也找到了办法。","explanation_cn":"even though,“即使、尽管”,引导让步。✓ Even though the tape was sticky, … ✗ if only / so / as:与 even 搭配的是 though。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp6','choice','{"stem":"\"A natural feeling or behavior you are born with is ___.\"(“本能”用哪个词)","options":["plan","instinct","choice","habit"],"answer_index":1,"stem_cn":"与生俱来的自然反应或行为。","explanation_cn":"与生俱来的自然反应或行为是 instinct。✓ was it pure instinct that guided them? ✗ habit 习惯;✗ plan 计划;✗ choice 选择——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp6','choice','{"stem":"\"A wall or obstacle that blocks the way is a ___.\"(“屏障、障碍”用哪个词)","options":["door","path","barrier","bridge"],"answer_index":2,"stem_cn":"挡住去路的墙或障碍。","explanation_cn":"挡住去路的墙或障碍是 barrier。✓ a small barrier of water. ✗ bridge 桥;✗ path 小路;✗ door 门——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',5,'am3_l54_gp6','choice','{"stem":"\"To respect and think highly of someone is to ___ them.\"(“钦佩”用哪个词)","options":["fear","admire","blame","ignore"],"answer_index":1,"stem_cn":"敬重、看重某人。","explanation_cn":"敬重、看重某人是 admire。✓ taught me to admire them. ✗ ignore 无视;✗ blame 责怪;✗ fear 害怕——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',6,NULL,'choice','{"stem":"instinct 的意思是:","options":["习惯","选择","本能","计划"],"answer_index":2,"explanation_cn":"instinct = 本能。✓ instinct or cleverness 本能还是机智。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',6,NULL,'choice','{"stem":"cleverness 的意思是:","options":["聪明,机智","胆怯","愚蠢","懒惰"],"answer_index":0,"explanation_cn":"cleverness = 聪明、机智。✓ their cleverness 它们的聪明。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',6,NULL,'choice','{"stem":"barrier 的意思是:","options":["入口","道路","屏障,障碍","桥梁"],"answer_index":2,"explanation_cn":"barrier = 屏障、障碍。✓ a barrier of water 一道水屏障。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',6,NULL,'choice','{"stem":"patient 的意思是:","options":["有耐心的","胆小的","急躁的","粗心的"],"answer_index":0,"explanation_cn":"patient = 有耐心的。✓ a long, patient line 一列长长的、耐心的队伍。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',6,NULL,'choice','{"stem":"admire 的意思是:","options":["忽视","害怕","钦佩,赞赏","责怪"],"answer_index":2,"explanation_cn":"admire = 钦佩、赞赏。✓ taught me to admire them 教我钦佩它们。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',6,NULL,'choice','{"stem":"defeat 的意思是:","options":["邀请","保护","帮助","击败,战胜"],"answer_index":3,"explanation_cn":"defeat = 击败、战胜。✓ defeated but amazed 被打败却又惊叹。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',7,NULL,'cloze','{"stem":"第 1 空","context":"Most of us are brought up ___1___ insects and treat them as pests. But last summer, some clever ants taught me ___2___ them instead. I was determined to protect my peach tree, so ___3___ them climb the trunk, I built a barrier of water around it. No matter ___4___ many barriers I made, the ants always found a way past.","blank_no":1,"options":["to fear","fearing","fear","feared"],"answer_index":0,"explanation_cn":"be brought up to do,“被教养成做…”。✓ brought up to fear insects."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',7,NULL,'cloze','{"stem":"第 2 空","context":"Most of us are brought up ___1___ insects and treat them as pests. But last summer, some clever ants taught me ___2___ them instead. I was determined to protect my peach tree, so ___3___ them climb the trunk, I built a barrier of water around it. No matter ___4___ many barriers I made, the ants always found a way past.","blank_no":2,"options":["to admire","admiring","admire","admired"],"answer_index":0,"explanation_cn":"teach sb to do,“教某人做…”。✓ taught me to admire them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',7,NULL,'cloze','{"stem":"第 3 空","context":"Most of us are brought up ___1___ insects and treat them as pests. But last summer, some clever ants taught me ___2___ them instead. I was determined to protect my peach tree, so ___3___ them climb the trunk, I built a barrier of water around it. No matter ___4___ many barriers I made, the ants always found a way past.","blank_no":3,"options":["watching","watched","watch","to watch"],"answer_index":0,"explanation_cn":"现在分词短语作状语,主动“看着…”。✓ watching them climb the trunk, I …"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',7,NULL,'cloze','{"stem":"第 4 空","context":"Most of us are brought up ___1___ insects and treat them as pests. But last summer, some clever ants taught me ___2___ them instead. I was determined to protect my peach tree, so ___3___ them climb the trunk, I built a barrier of water around it. No matter ___4___ many barriers I made, the ants always found a way past.","blank_no":4,"options":["how","what","which","that"],"answer_index":0,"explanation_cn":"no matter how + many,“无论多少”。✓ No matter how many barriers I made …"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',8,NULL,'choice','{"stem":"Was the writer successful in protecting his peach tree?","options":["No — the tree died first","Yes — he sprayed the tree","No — the ants outsmarted every barrier and found new routes","Yes — the water barrier stopped them"],"answer_index":2,"explanation_cn":"录音说无论作者筑多少屏障,蚂蚁都能绕过、另找新路,所以他没能保住桃树。✓ ants found new routes."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',8,NULL,'choice','{"stem":"What did the ants use to cross the barrier of water?","options":["Nothing at all","A stone","A small stick","A fallen leaf as a bridge"],"answer_index":3,"explanation_cn":"录音说蚂蚁用一片落叶当桥,渡过了那圈水。✓ a fallen leaf as a bridge."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',8,NULL,'choice','{"stem":"How did the writer feel about the ants in the end?","options":["Frightened","Defeated but amazed, still admiring their cleverness","Angry and disgusted","Bored and indifferent"],"answer_index":1,"explanation_cn":"录音说作者虽被彻底打败,却满心惊叹,反而钦佩蚂蚁的聪明。✓ defeated but amazed."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',9,NULL,'choice','{"stem":"你想说\"我决心保护我的桃树\"(be determined to do):","options":["I was determined to protect my peach tree.","I was determined protect my peach tree.","I was determined to protecting my peach tree.","I was determined protecting my peach tree."],"answer_index":0,"explanation_cn":"be determined to do,后接不定式 to protect;不用 -ing、不用原形、不用 to + -ing。✓ determined to protect … 场合:表达“决心做…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',9,NULL,'choice','{"stem":"你想说\"看着它们爬上树干,我决定动手\"(现在分词状语):","options":["Watch them climb the trunk, I decided to act.","Watching them climb the trunk, I decided to act.","Watched them climb the trunk, I decided to act.","To watch them climb the trunk, I decided to act."],"answer_index":1,"explanation_cn":"现在分词作状语用主动 Watching;不用 Watched/Watch/To watch,逻辑动作者是主句的 I。✓ Watching them climb, I … 场合:表达“…时,我…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',9,NULL,'choice','{"stem":"你想说\"无论我筑多少屏障,蚂蚁都能过去\"(no matter how):","options":["No matter how many barriers I built, the ants gets past.","No matter many barriers how I built, the ants got past.","No matter what many barriers I built, the ants got past.","No matter how many barriers I built, the ants got past."],"answer_index":3,"explanation_cn":"no matter how many + 名词;主句里 ants 是复数,动词用 got;语序 how many barriers 不能拆。✓ No matter how many barriers I built, … 场合:表达“无论多少…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"instinct 的意思是:","options":["计划","本能","习惯","选择"],"answer_index":1,"explanation_cn":"instinct = 本能。✓ was it instinct that guided them?"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"admire 的意思是:","options":["钦佩,赞赏","忽视","害怕","责怪"],"answer_index":0,"explanation_cn":"admire = 钦佩、赞赏。✓ taught me to admire them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"\"I was determined ___ my peach tree from the ants.\"(be determined ___ do:决心做)","options":["protect","protecting","to protect","protected"],"answer_index":2,"stem_cn":"我决心保护我的桃树不被蚂蚁侵害。","explanation_cn":"be determined to do,后接不定式。✓ determined to protect it. ✗ protecting / protect / protected。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"\"___ them march up the trunk, I decided to act.\"(现在分词短语作状语:看着…)","options":["Watch","Watching","To watch","Watched"],"answer_index":1,"stem_cn":"看着它们爬上树干,我决定动手。","explanation_cn":"现在分词短语作状语,主动用 Watching。✓ Watching them climb, I … ✗ Watched / Watch / To watch。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"\"give up\" 的意思是:","options":["加入","举起","分发","放弃"],"answer_index":3,"explanation_cn":"give up = 放弃。✓ gave up trying to outwit them 放弃了斗智。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"\"bring up\" 的意思是:","options":["养育、教养","拆开","加速","忘记"],"answer_index":0,"explanation_cn":"bring up = 养育、教养。✓ brought up to fear insects 自幼被教得害怕昆虫。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"Why did the writer build a barrier of water around the peach tree?","options":["To attract more insects","To decorate the yard","To water the tree","To stop the ants from reaching the fruit"],"answer_index":3,"passage":"Most of us are brought up to fear insects, seeing them as pests we would rather avoid. We swat at flies, step around spiders, and shoo ants away from our food. Yet last summer, a line of tiny ants taught me to admire them instead. My peach tree had grown against a warm, sheltered wall, and by August it was full of ripe, delicious fruit. I was especially proud of that tree, and I was determined to protect it from the ants that came marching up the trunk in a long, patient line. Watching them climb, I decided to build a small barrier of water around the base, certain that no ant could cross it. Feeling clever, I sat back to enjoy my victory. But within an hour, the ants had found a way across, using a fallen leaf as a bridge. I cleared the leaf away, only to watch them try another. No matter how many barriers I built, they always managed to get past. I even went out at midnight with a flashlight and saw them still swarming around my defenses, working patiently in the dark. Early the next morning, hoping to find that they had given up, I instead discovered a brand-new route: they were climbing the wall of the house and dropping straight onto the leaves. I kept finding new columns of ants every hour, and I could not stop admiring their patience. Defeated but amazed, I finally gave up trying to outwit them and let them share the fruit. I still wonder whether it was pure instinct that guided them, or whether they were simply cleverer than I was. Losing to an ant, I have learned, is nothing to be ashamed of. There is something to admire in a creature so small that never gives up.","explanation_cn":"课文说作者在树根围一圈水做屏障,是为了阻止蚂蚁爬上去够到果子。✓ stop the ants reaching the fruit."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"How did the ants finally reach the leaves after the writer''s midnight check?","options":["They flew over it","They climbed the wall of the house and dropped onto the leaves","They gave up completely","They dug under the barrier"],"answer_index":1,"passage":"Most of us are brought up to fear insects, seeing them as pests we would rather avoid. We swat at flies, step around spiders, and shoo ants away from our food. Yet last summer, a line of tiny ants taught me to admire them instead. My peach tree had grown against a warm, sheltered wall, and by August it was full of ripe, delicious fruit. I was especially proud of that tree, and I was determined to protect it from the ants that came marching up the trunk in a long, patient line. Watching them climb, I decided to build a small barrier of water around the base, certain that no ant could cross it. Feeling clever, I sat back to enjoy my victory. But within an hour, the ants had found a way across, using a fallen leaf as a bridge. I cleared the leaf away, only to watch them try another. No matter how many barriers I built, they always managed to get past. I even went out at midnight with a flashlight and saw them still swarming around my defenses, working patiently in the dark. Early the next morning, hoping to find that they had given up, I instead discovered a brand-new route: they were climbing the wall of the house and dropping straight onto the leaves. I kept finding new columns of ants every hour, and I could not stop admiring their patience. Defeated but amazed, I finally gave up trying to outwit them and let them share the fruit. I still wonder whether it was pure instinct that guided them, or whether they were simply cleverer than I was. Losing to an ant, I have learned, is nothing to be ashamed of. There is something to admire in a creature so small that never gives up.","explanation_cn":"课文说第二天早上作者发现蚂蚁找到新路:顺房子外墙往上爬,再直接落到树叶上。✓ climbed the wall and dropped onto the leaves."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"What did the writer conclude he could not be sure of?","options":["Whether the ants were dangerous","Whether the tree would survive","Whether it was instinct or cleverness that guided the ants","How many ants there were"],"answer_index":2,"audio":"Most of us are brought up to fear insects, seeing them as pests we would rather avoid. We swat at flies, step around spiders, and shoo ants away from our food. Yet last summer, a line of tiny ants taught me to admire them instead. My peach tree had grown against a warm, sheltered wall, and by August it was full of ripe, delicious fruit. I was especially proud of that tree, and I was determined to protect it from the ants that came marching up the trunk in a long, patient line. Watching them climb, I decided to build a small barrier of water around the base, certain that no ant could cross it. Feeling clever, I sat back to enjoy my victory. But within an hour, the ants had found a way across, using a fallen leaf as a bridge. I cleared the leaf away, only to watch them try another. No matter how many barriers I built, they always managed to get past. I even went out at midnight with a flashlight and saw them still swarming around my defenses, working patiently in the dark. Early the next morning, hoping to find that they had given up, I instead discovered a brand-new route: they were climbing the wall of the house and dropping straight onto the leaves. I kept finding new columns of ants every hour, and I could not stop admiring their patience. Defeated but amazed, I finally gave up trying to outwit them and let them share the fruit. I still wonder whether it was pure instinct that guided them, or whether they were simply cleverer than I was. Losing to an ant, I have learned, is nothing to be ashamed of. There is something to admire in a creature so small that never gives up.","explanation_cn":"课文结尾说作者仍拿不准:指引蚂蚁的到底是本能,还是它们真比自己聪明。✓ instinct or cleverness."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l54',10,NULL,'choice','{"stem":"What lesson did the writer say he learned?","options":["Peach trees are not worth the trouble","Insects should always be feared","Water barriers never work","Losing to an ant is nothing to be ashamed of"],"answer_index":3,"audio":"Most of us are brought up to fear insects, seeing them as pests we would rather avoid. We swat at flies, step around spiders, and shoo ants away from our food. Yet last summer, a line of tiny ants taught me to admire them instead. My peach tree had grown against a warm, sheltered wall, and by August it was full of ripe, delicious fruit. I was especially proud of that tree, and I was determined to protect it from the ants that came marching up the trunk in a long, patient line. Watching them climb, I decided to build a small barrier of water around the base, certain that no ant could cross it. Feeling clever, I sat back to enjoy my victory. But within an hour, the ants had found a way across, using a fallen leaf as a bridge. I cleared the leaf away, only to watch them try another. No matter how many barriers I built, they always managed to get past. I even went out at midnight with a flashlight and saw them still swarming around my defenses, working patiently in the dark. Early the next morning, hoping to find that they had given up, I instead discovered a brand-new route: they were climbing the wall of the house and dropping straight onto the leaves. I kept finding new columns of ants every hour, and I could not stop admiring their patience. Defeated but amazed, I finally gave up trying to outwit them and let them share the fruit. I still wonder whether it was pure instinct that guided them, or whether they were simply cleverer than I was. Losing to an ant, I have learned, is nothing to be ashamed of. There is something to admire in a creature so small that never gives up.","explanation_cn":"课文说作者懂得了:输给一只蚂蚁,没什么好羞愧的。✓ nothing to be ashamed of."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
